/**
 * Mapping merk → material_subtype_id berdasarkan nama subtype di DB:
 *  Lyse       : blood cell diluents, lyse reagent, red cell lysing
 *  Cleanser   : cleaning solution, cleanser/wash solution
 *  Tuberkulin : tuberculin
 *  Thermal Paper: ECG Paper
 *  Reagen     : default (test kit, test strip, reagent, dll)
 */
function getSubtypeId(merk: string, subtypeIdByName: Map<string, number>): number {
  const m = merk.toLowerCase()
  if (m.includes('diluent') || m.includes('lyse') || m.includes('lysing'))
    return subtypeIdByName.get('lyse') ?? subtypeIdByName.get('reagen')!
  if (m.includes('cleanser') || m.includes('cleaning') || m.includes('wash'))
    return subtypeIdByName.get('cleanser') ?? subtypeIdByName.get('reagen')!
  if (m.includes('tuberculin'))
    return subtypeIdByName.get('tuberkulin') ?? subtypeIdByName.get('reagen')!
  if (m.includes('ecg paper'))
    return subtypeIdByName.get('thermal paper') ?? subtypeIdByName.get('reagen')!
  return subtypeIdByName.get('reagen')!
}

export async function up(db: Kysely<any>): Promise<void> {
  // 0a. Lookup unit IDs by name dari material_units
  const unitRows: any[] = await db
    .selectFrom("material_units")
    .select(["id", "name"])
    .where("name", "in", ["pcs", "box"])
    .execute()
  const unitIdByName = new Map<string, number>(unitRows.map((r: any) => [r.name.toLowerCase(), Number(r.id)]))
  const unitOfConsumptionId = unitIdByName.get("pcs")
  const unitOfDistributionId = unitIdByName.get("box")
  if (!unitOfConsumptionId || !unitOfDistributionId) throw new Error("Unit 'pcs' atau 'box' tidak ditemukan di material_units")

  // 0. Lookup material_subtypes by name → id (type_id = 4)
  const subtypeRows: any[] = await db
    .selectFrom("material_subtypes")
    .select(["id", "name"])
    .where("material_type_id", "=", 4)
    .where("deleted_at", "is", null)
    .execute()
  const subtypeIdByName = new Map<string, number>(
    subtypeRows.map((r) => [r.name.toLowerCase().trim(), Number(r.id)])
  )

  // 1. Lookup materials level 2 by Merk name → id
  const lv2Rows: any[] = await db
    .selectFrom("materials")
    .select(["id", "name"])
    .where("material_level_id", "=", 2)
    .where("deleted_at", "is", null)
    .execute()
  const lv2ByName = new Map<string, number>(
    lv2Rows.map((r) => [r.name.toLowerCase().trim(), Number(r.id)])
  )

  // 2. Lookup ws_bmhp_material_variant by material_id → variant_id
  const variantRows: any[] = await db
    .selectFrom("ws_bmhp_material_variant")
    .select(["id", "material_id"])
    .where("deleted_at", "is", null)
    .execute()
  const variantIdByMaterialId = new Map<number, number>(
    variantRows.map((r) => [Number(r.material_id), Number(r.id)])
  )

  // 3. Cek materials level 3 yang sudah ada (by code, untuk idempotent)
  const existingLv3: any[] = await db
    .selectFrom("materials")
    .select("code")
    .where("code", "like", "PKG-NMD-V-%")
    .where("deleted_at", "is", null)
    .execute()
  const existingLv3Codes = new Set(existingLv3.map((r: any) => r.code))

  // 4. Insert materials level 3 (skip yang sudah ada)
  const toInsertMaterials = VARIANT_DATA.filter((v) => !existingLv3Codes.has(v.code))

  const BATCH = 50
  for (let i = 0; i < toInsertMaterials.length; i += BATCH) {
    const batch = toInsertMaterials.slice(i, i + BATCH).map((v) => ({
      name: v.name,
      code: v.code,
      material_level_id: 3,
      material_type_id: 4,
      material_subtype_id: getSubtypeId(v.merk, subtypeIdByName),
      unit_of_consumption_id: unitOfConsumptionId,
      unit_of_distribution_id: unitOfDistributionId,
      consumption_unit_per_distribution_unit: 1,
      is_temperature_sensitive: 0,
      min_retail_price: 0,
      max_retail_price: 0,
      is_managed_in_batch: 1,
      status: 1,
      created_by: 1,
      updated_by: 1,
      is_kfa: 1,
      is_stock_opname_mandatory: 0,
    }))
    await db.insertInto("materials").values(batch).execute()
  }

  // 5. Fetch semua level 3 by code → dapat id
  const allCodes = VARIANT_DATA.map((v) => v.code)
  const lv3Rows: any[] = await db
    .selectFrom("materials")
    .select(["id", "code"])
    .where("code", "in", allCodes)
    .where("deleted_at", "is", null)
    .execute()
  const lv3IdByCode = new Map<string, number>(
    lv3Rows.map((r) => [r.code, Number(r.id)])
  )

  // 5b. Insert material_workspaces untuk level 3 yang baru diinsert
  const existingWorkspaces: any[] = await db
    .selectFrom("material_workspaces")
    .select("material_id")
    .where("material_id", "in", Array.from(lv3IdByCode.values()))
    .execute()
  const existingWorkspaceMaterialIds = new Set(existingWorkspaces.map((r: any) => Number(r.material_id)))

  const workspacesToInsert = Array.from(lv3IdByCode.values())
    .filter((id) => !existingWorkspaceMaterialIds.has(id))
    .map((id) => ({ material_id: id, workspace_id: 39, status: 1 }))

  for (let i = 0; i < workspacesToInsert.length; i += BATCH) {
    await db.insertInto("material_workspaces").values(workspacesToInsert.slice(i, i + BATCH)).execute()
  }

  // 6. Build material_relations (parent=lv2.id, child=lv3.id)
  const existingRelations: any[] = await db
    .selectFrom("material_relations")
    .select(["child_material_id"])
    .execute()
  const existingChildIds = new Set(existingRelations.map((r: any) => Number(r.child_material_id)))

  const relationsToInsert: Array<{ parent_material_id: number; child_material_id: number }> = []
  for (const v of VARIANT_DATA) {
    const lv3Id = lv3IdByCode.get(v.code)
    if (!lv3Id) continue
    if (existingChildIds.has(lv3Id)) continue
    const lv2Id = lv2ByName.get(v.merk.toLowerCase().trim())
    if (!lv2Id) continue
    relationsToInsert.push({ parent_material_id: lv2Id, child_material_id: lv3Id })
  }

  for (let i = 0; i < relationsToInsert.length; i += BATCH) {
    await db.insertInto("material_relations").values(relationsToInsert.slice(i, i + BATCH)).execute()
  }

  // 7. Build ws_bmhp_material_variant_detail
  const existingDetails: any[] = await db
    .selectFrom("ws_bmhp_material_variant_detail")
    .select(["material_id"])
    .where("deleted_at", "is", null)
    .execute()
  const existingDetailMaterialIds = new Set(existingDetails.map((r: any) => Number(r.material_id)))

  const detailsToInsert: Array<{
    material_variant_id: number
    material_id: number
    name: string
    test_qty: number | null
    unit_id: number | null
  }> = []

  for (const v of VARIANT_DATA) {
    const lv3Id = lv3IdByCode.get(v.code)
    if (!lv3Id) continue
    if (existingDetailMaterialIds.has(lv3Id)) continue

    const lv2Id = lv2ByName.get(v.merk.toLowerCase().trim())
    if (!lv2Id) continue
    const variantId = variantIdByMaterialId.get(lv2Id)
    if (!variantId) continue

    detailsToInsert.push({
      material_variant_id: variantId,
      material_id: lv3Id,
      name: v.name,
      test_qty: v.testQty,
      unit_id: v.unitId,
    })
  }

  for (let i = 0; i < detailsToInsert.length; i += BATCH) {
    await db.insertInto("ws_bmhp_material_variant_detail").values(detailsToInsert.slice(i, i + BATCH)).execute()
  }
}

export async function down(db: Kysely<any>): Promise<void> {
  // Fetch all PKG-NMD-V-* materials
  const lv3Rows: any[] = await db
    .selectFrom("materials")
    .select("id")
    .where("code", "like", "PKG-NMD-V-%")
    .execute()
  const lv3Ids = lv3Rows.map((r: any) => Number(r.id))

  if (lv3Ids.length === 0) return

  await db
    .deleteFrom("ws_bmhp_material_variant_detail")
    .where("material_id", "in", lv3Ids)
    .execute()

  await db
    .deleteFrom("material_relations")
    .where("child_material_id", "in", lv3Ids)
    .execute()

  await db
    .deleteFrom("material_workspaces")
    .where("material_id", "in", lv3Ids)
    .execute()

  await db
    .deleteFrom("materials")
    .where("id", "in", lv3Ids)
    .execute()
}
